<script setup lang="ts">import {ref,computed} from 'vue';import {Search,MapPin,BadgeCheck,SlidersHorizontal,ArrowRight,Star} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {workshops} from '../data/customer';const search=ref('');const partner=ref(false);const service=ref('All services');const location=ref('All locations');const brand=ref('All brands');const shown=computed(()=>workshops.filter(w=>(!partner.value||w.partner)&&(service.value==='All services'||w.services.includes(service.value))&&(location.value==='All locations'||w.location===location.value)&&(brand.value==='All brands'||w.brands.includes(brand.value)||w.brands.includes('All brands'))&&`${w.name} ${w.location} ${w.brands.join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
</script>
<template><PageHeader title="Workshops" back="/"/><div class="container-app max-w-5xl py-7"><p class="eyebrow">Workshop directory</p><h1 class="page-title mt-2">Find the right workshop</h1><p class="mt-3 text-muted">Search by location, service or supported vehicle brand.</p><div class="mt-7 grid gap-3 md:grid-cols-2 xl:grid-cols-[1fr_150px_150px_180px_auto]"><label class="relative"><Search :size="18" class="absolute left-4 top-3.5 text-muted"/><input v-model="search" class="field pl-11" placeholder="Workshop, location or brand"/></label><select v-model="location" class="field"><option>All locations</option><option>Ljubljana</option><option>Škofja Loka</option></select><select v-model="brand" class="field"><option>All brands</option><option>BMW</option><option>MINI</option><option>Volkswagen</option><option>Audi</option></select><select v-model="service" class="field"><option>All services</option><option>Regular service</option><option>Brakes</option><option>Tyres</option><option>Body repair</option></select><button @click="partner=!partner" class="btn-secondary" :class="{'!border-accent !bg-emerald-50 !text-accent':partner}"><SlidersHorizontal :size="17"/>Vintro Partners</button></div><div class="mt-7 grid gap-4 md:grid-cols-2"><RouterLink v-for="w in shown" :key="w.id" :to="`/workshops/${w.id}`" class="card group p-5 hover:shadow-soft"><div class="flex items-start justify-between"><span class="grid h-12 w-12 place-items-center rounded-xl bg-stone-100 text-lg font-semibold">{{w.name.charAt(0)}}</span><span v-if="w.partner" class="flex items-center gap-1 text-xs font-semibold text-success"><BadgeCheck :size="16"/>Vintro Partner</span></div><h2 class="mt-5 text-lg font-semibold">{{w.name}}</h2><p class="mt-1 flex items-center gap-1.5 text-sm text-muted"><MapPin :size="15"/>{{w.location}} · {{w.distance}}</p><p class="mt-2 flex items-center gap-1 text-sm"><Star :size="15" class="fill-amber text-amber"/><strong>{{w.rating}}</strong><span class="text-muted">({{w.reviews}} reviews)</span></p><div class="mt-4 flex flex-wrap gap-2"><span v-for="s in w.services.slice(0,3)" class="rounded-full bg-stone-100 px-2.5 py-1 text-xs">{{s}}</span></div><div v-if="w.benefit" class="mt-5 border-t pt-4 text-sm font-medium text-accent">{{w.benefit}}</div><div class="mt-4 flex items-center justify-end gap-1 text-sm font-semibold">View workshop<ArrowRight :size="16" class="transition group-hover:translate-x-1"/></div></RouterLink></div><div v-if="!shown.length" class="mt-8 rounded-2xl border border-dashed p-10 text-center text-muted">No workshops match these filters.</div></div></template>
